<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useWorkspace } from '../../state/workspace'
import { useSimulator } from '../../state/simulator'
import type { WorkspacePaper } from '../../data/workspace'
import { answerLetters, clone, correctIds, isoNow, matches, newId, shuffled, usePagination } from './lib/domain'
import WorkspacePager from './WorkspacePager.vue'
import ConfirmDialog from './ConfirmDialog.vue'
import BaseModal from '../common/BaseModal.vue'
import UiIcon from '../common/UiIcon.vue'
const workspace = useWorkspace(), simulator = useSimulator(), search = ref(''), questionSearch = ref(''), outline = ref(''), chosenAvailable = ref<string[]>([]), chosenSelected = ref<string[]>([]), fileInput = ref<HTMLInputElement>()
const selectedId = ref(workspace.data.papers[0]?.id || ''), preview = ref(false), removing = ref(false), autoDialog = ref(false), autoCount = ref(20), autoTag = ref('T11'), autoError = ref('')
function emptyPaper(): WorkspacePaper { return { id: newId('paper'), title: '', description: '', questionIds: [], durationMinutes: 60, maxScore: 100, passPercent: 60, shuffle: false, createdAt: isoNow(), updatedAt: isoNow() } }
const draft = ref<WorkspacePaper>(workspace.data.papers[0] ? clone(workspace.data.papers[0]) : emptyPaper())
const papers = computed(() => workspace.data.papers.filter(paper => matches(`${paper.title} ${paper.description}`, search.value)))
const { page, pageSize, rows } = usePagination(papers, 5)
const available = computed(() => workspace.data.questions.filter(question => !draft.value.questionIds.includes(question.id) && (!outline.value || question.tags.includes(outline.value)) && matches(`${question.content} ${question.tags.join(' ')}`, questionSearch.value)))
const selected = computed(() => draft.value.questionIds.flatMap(id => { const question = workspace.data.questions.find(question => question.id === id); return question ? [question] : [] }))
const autoPool = computed(() => workspace.data.questions.filter(question => !autoTag.value || question.tags.includes(autoTag.value)))
watch([questionSearch, outline], () => { chosenAvailable.value = [] })
watch(search, () => { page.value = 1 })
function select(paper: WorkspacePaper) { selectedId.value = paper.id; draft.value = clone(paper); chosenAvailable.value = []; chosenSelected.value = [] }
function create() { selectedId.value = ''; draft.value = emptyPaper(); chosenAvailable.value = []; chosenSelected.value = [] }
function save() { if (workspace.savePaper(draft.value)) selectedId.value = draft.value.id }
function add(ids: string[]) { draft.value.questionIds = [...new Set([...draft.value.questionIds, ...ids])]; chosenAvailable.value = [] }
function removeSelected() { draft.value.questionIds = draft.value.questionIds.filter(id => !chosenSelected.value.includes(id)); chosenSelected.value = [] }
function move(id: string, delta: number) { const index = draft.value.questionIds.indexOf(id), next = index + delta; if (next < 0 || next >= draft.value.questionIds.length) return; const ids = [...draft.value.questionIds]; [ids[index], ids[next]] = [ids[next]!, ids[index]!]; draft.value.questionIds = ids }
function deletePaper() { if (workspace.deletePaper(draft.value.id)) { const next = workspace.data.papers[0]; if (next) select(next); else create() }; removing.value = false }
function exportPaper() { if (!selected.value.length) { simulator.notify('请选择题目后再导出试卷。', 'warning'); return }; simulator.downloadJson(`试卷-${workspace.safeName(draft.value.title || '未命名')}.json`, { schemaVersion: 3, papers: [draft.value], questions: selected.value }) }
async function importPaper(event: Event) { const input = event.target as HTMLInputElement, file = input.files?.[0]; if (!file) return; try { if (file.size > 12 * 1024 * 1024) throw new Error('试卷文件最大 12 MB。'); if (workspace.importPapers(await file.text()) && workspace.data.papers[0]) select(workspace.data.papers[0]) } catch (error) { simulator.notify(error instanceof Error ? error.message : '试卷读取失败。', 'warning') }; input.value = '' }
function assemble() {
  if (!Number.isInteger(autoCount.value) || autoCount.value < 1 || autoCount.value > autoPool.value.length) { autoError.value = `请输入 1～${autoPool.value.length} 之间的题数。`; return }
  create(); draft.value.title = `${autoTag.value || '综合'} 随机组卷 ${new Date().toLocaleTimeString('zh-CN')}`; draft.value.description = `从 ${autoTag.value || '全部'} 本地题库随机抽取 ${autoCount.value} 题。`; draft.value.questionIds = shuffled(autoPool.value).slice(0, autoCount.value).map(question => question.id); autoDialog.value = false; autoError.value = ''
}
function createTask() { if (workspace.savePaper(draft.value)) { simulator.state.workspaces.taskPaperId = draft.value.id; workspace.data.teacherTab = 'tasks' } }
</script>
<template>
  <div class="toolbar"><h2 style="margin:0;font-size:18px">试卷管理 / 组卷</h2><span class="spacer" /><button class="btn" @click="fileInput?.click()">导入试卷</button><button class="btn" @click="exportPaper">导出当前试卷</button><button class="btn" @click="autoDialog = true"><UiIcon name="Shuffle" :size="15" />自动组卷</button><input ref="fileInput" type="file" accept=".json" hidden @change="importPaper" /></div>
  <div class="ws-split">
    <aside class="ws-panel"><header class="ws-panel-header"><h3>试卷列表</h3><span class="badge">{{ papers.length }} 套</span></header><div class="ws-panel-body"><input v-model="search" class="field" placeholder="搜索试卷名称 / 描述" style="margin-bottom:12px" /><div class="ws-list"><button v-for="paper in rows" :key="paper.id" class="ws-list-row" :class="{ active: selectedId === paper.id }" @click="select(paper)"><UiIcon name="Files" :size="17" /><div><strong>{{ paper.title }}</strong><small>{{ paper.questionIds.length }} 题 · {{ paper.maxScore }} 分 · {{ paper.durationMinutes }} 分钟</small></div></button><div v-if="!papers.length" class="empty-state">暂无试卷，点击新增组卷</div></div><WorkspacePager v-model:page="page" v-model:page-size="pageSize" :total="papers.length" :sizes="[5, 10, 20]" /><button class="btn btn-primary" style="width:100%;margin-top:15px" @click="create"><UiIcon name="Plus" :size="15" />新增试卷</button></div></aside>
    <section class="ws-panel"><header class="ws-panel-header"><h3>试卷编辑</h3><div class="ws-inline"><button class="btn btn-sm" :disabled="!selected.length" @click="preview = true">试卷预览</button><button class="btn btn-sm btn-primary" @click="save">保存试卷</button></div></header><div class="ws-panel-body">
      <div class="form-grid"><label class="field-group"><span>试卷名称 *</span><input v-model="draft.title" class="field" maxlength="120" placeholder="请输入试卷名称" /></label><label class="field-group"><span>考试时长（分钟）</span><input v-model.number="draft.durationMinutes" type="number" min="1" max="1440" class="field" /></label><label class="field-group full"><span>试卷描述</span><textarea v-model="draft.description" class="field" rows="2" /></label><label class="field-group"><span>试卷总分</span><input v-model.number="draft.maxScore" class="field" type="number" min="1" max="10000" /></label><label class="field-group"><span>通过比例（%）</span><input v-model.number="draft.passPercent" class="field" type="number" min="0" max="100" /></label><label class="checkbox-label full"><input v-model="draft.shuffle" type="checkbox" />任务发布时随机排列试题</label></div>
      <hr class="ws-divider" /><h3>题目选择</h3><div class="toolbar"><span class="ws-form-label" style="margin:0">考试大纲：</span><select v-model="outline" class="field" style="width:130px"><option value="">全部</option><option value="T11">T11</option><option value="T12">T12</option><option v-for="tag in workspace.tags.value.filter(item => !['T11', 'T12'].includes(item))" :key="tag">{{ tag }}</option></select><input v-model="questionSearch" class="field" style="max-width:290px" placeholder="搜索题目关键词" /><button class="btn" @click="questionSearch = ''; outline = ''">重置筛选</button><span class="spacer" /><span class="badge">已选 {{ selected.length }} 题 · 按权重折算 {{ draft.maxScore }} 分</span></div>
      <div class="ws-transfer"><div><div class="ws-transfer-title">当前题库<span>{{ available.length }} 题</span></div><div class="ws-transfer-list"><label v-for="question in available" :key="question.id" class="checkbox-label"><input v-model="chosenAvailable" type="checkbox" :value="question.id" /><span>{{ question.content }}<small class="ws-subtext" style="display:block">{{ question.type }} · {{ question.tags.join(' / ') }}</small></span></label><div v-if="!available.length" class="empty-state">没有可添加题目</div></div></div>
        <div class="ws-transfer-arrows"><button class="btn btn-sm" :disabled="!chosenAvailable.length" @click="add(chosenAvailable)">添加 ⇛</button><button class="btn btn-sm" :disabled="!available.length" @click="add(available.map(question => question.id))">全部 ⇛</button><button class="btn btn-sm" :disabled="!chosenSelected.length" @click="removeSelected">⇚ 移除</button><button class="btn btn-sm" :disabled="!selected.length" @click="draft.questionIds = []; chosenSelected = []">⇚ 清空</button></div>
        <div><div class="ws-transfer-title">已选题目<span>{{ selected.length }} 题</span></div><div class="ws-transfer-list"><div v-for="(question, index) in selected" :key="question.id" class="ws-check-row" style="margin-bottom:6px;align-items:flex-start"><input v-model="chosenSelected" type="checkbox" :value="question.id" /><div style="flex:1;font-size:12px;line-height:1.7">{{ index + 1 }}. {{ question.content }}</div><div class="ws-small-stack" style="gap:3px"><button class="btn btn-sm" title="上移" :disabled="index === 0" @click="move(question.id, -1)">↑</button><button class="btn btn-sm" title="下移" :disabled="index === selected.length - 1" @click="move(question.id, 1)">↓</button></div></div><div v-if="!selected.length" class="empty-state">从左侧选择题目并添加</div></div></div></div>
      <div class="form-actions"><button class="btn btn-danger" :disabled="!selectedId" @click="removing = true">删除试卷</button><span class="spacer" /><button class="btn" :disabled="!selected.length" @click="createTask">设置练习 / 考试任务</button><button class="btn btn-primary" @click="save"><UiIcon name="Save" :size="15" />保存试卷</button></div>
    </div></section>
  </div>
  <ConfirmDialog v-if="removing" title="删除试卷" :message="`确定删除试卷“${draft.title}”？已发布任务和成绩快照保留，尚未发布的引用任务需要先调整。`" danger @confirm="deletePaper" @close="removing = false" />
  <BaseModal v-if="preview" :title="'试卷预览 · ' + (draft.title || '未命名试卷')" :width="900" @close="preview = false"><div class="ws-modal-content"><div class="ws-note">{{ selected.length }} 题 · {{ draft.maxScore }} 分 · {{ draft.durationMinutes }} 分钟 · 通过比例 {{ draft.passPercent }}%。此处为教师预览，包含正确答案。</div><section v-for="(question, index) in selected" :key="question.id" style="margin-bottom:22px"><h3 style="line-height:1.8">{{ index + 1 }}. {{ question.content }} <span class="badge">{{ question.type }}</span></h3><div v-for="(option, optionIndex) in question.options" :key="option.id" class="ws-check-row" style="margin-bottom:6px" :style="option.correct ? { borderColor: '#a0cbb7', background: '#f0f9f4' } : {}"><span class="ws-option-letter">{{ String.fromCharCode(65 + optionIndex) }}</span>{{ option.text }}<UiIcon v-if="option.correct" name="Check" :size="15" class="ws-success" /></div><p class="ws-subtext" style="margin-top:10px">正确答案：{{ answerLetters(question, correctIds(question)) }}</p></section></div><template #footer><button class="btn" @click="preview = false">关闭</button></template></BaseModal>
  <BaseModal v-if="autoDialog" title="自动组卷 · 随机抽题" :width="500" @close="autoDialog = false"><div class="ws-modal-content ws-stack"><label class="field-group"><span>题库 / 考试大纲</span><select v-model="autoTag" class="field"><option value="">全部</option><option v-for="tag in workspace.tags.value" :key="tag">{{ tag }}</option></select></label><label class="field-group"><span>抽取题数（当前可用 {{ autoPool.length }} 题）</span><input v-model.number="autoCount" type="number" class="field" min="1" :max="autoPool.length" /></label><div v-if="autoError" class="ws-form-error">{{ autoError }}</div><div class="ws-note">随机抽题只生成当前编辑草稿。检查题目后点击“保存试卷”，不会自动发布或生成成绩。</div></div><template #footer><button class="btn" @click="autoDialog = false">取消</button><button class="btn btn-primary" @click="assemble">生成试卷草稿</button></template></BaseModal>
</template>
